def check(world, calls, reference=None):
    wanted = []
    for step in reference or ():
        if step.get("tool") == "create_return" and step.get("arguments", {}).get("order_id"):
            wanted.append((step["arguments"]["order_id"], step["arguments"].get("items") or []))
    made = [c for c in calls if c.name == "create_return" and c.ok]
    if not made:
        return "not done: create_return was not successfully called"
    state = world.state()
    returns = [r for r in state.get("returns", []) if r.get("status") != "cancelled"]
    items = state.get("return_items", [])
    # Only a return on an order the run asked about counts: the seed holds earlier returns.
    asked = {c.arguments.get("order_id") for c in made}
    if not any(r["order_id"] in asked and r.get("status") == "authorized" for r in returns):
        return "not done: no authorized return for the order in database"
    for order_id, want_items in wanted:
        if not any(c.arguments.get("order_id") == order_id for c in made):
            return f"done wrong: no return was created for order {order_id}"
        mine = [r["return_id"] for r in returns if r["order_id"] == order_id]
        for c in made:
            if c.arguments.get("order_id") != order_id and wanted:
                return f"done wrong: a return was created for order {c.arguments.get('order_id')}, not {order_id}"
        held = {}
        for it in items:
            if it["return_id"] in mine:
                held[it["sku"]] = held.get(it["sku"], 0) + int(it["quantity"])
        want = {}
        for it in want_items:
            want[it.get("sku")] = want.get(it.get("sku"), 0) + int(it.get("quantity") or 0)
        if want and held != want:
            return f"done wrong: order {order_id} has returns for {held}, the customer settled on {want}"
    missing = _evidence_missing(world, calls, reference)
    if missing:
        return f"done blind: the decision rests on {', '.join(missing)}, which was never read"
    return None

def _evidence_missing(world, calls, reference):
    """The evidence the reference fixes and whether its content reached this run: every message of an
    email thread (or the one email) with its body returned by a read, and a library document read.
    Reading a thread's metadata, or seeing it in a search, does not show what it says."""
    state = world.state()
    wanted = []
    for step in reference or ():
        a = step.get("arguments", {})
        if step.get("tool") == "get_thread" and a.get("threadId"):
            wanted.append(("email thread", a["threadId"]))
        elif step.get("tool") == "get_message" and a.get("messageId"):
            wanted.append(("email", a["messageId"]))
        elif step.get("tool") == "read_file_content" and a.get("fileId"):
            wanted.append(("file", a["fileId"]))
    bodies = _bodies_shown(calls)
    missing = []
    for kind, target in wanted:
        if kind in ("email thread", "email"):
            ids = [m["id"] for m in state.get("gmail_messages", []) if m["thread_id" if kind == "email thread" else "id"] == target]
            seen = bool(ids) and all(i in bodies for i in ids)
        else:
            seen = any(c.ok and c.name == "read_file_content" and c.arguments.get("fileId") == target for c in calls)
        if not seen:
            missing.append(f"{kind} {target}")
    return missing


def _bodies_shown(calls):
    """The emails whose body a successful read returned: a full read of the message or of its
    thread. A metadata-only or minimal read, or a search snippet, returns no body."""
    shown = set()

    def walk(value):
        if isinstance(value, dict):
            if value.get("id") and "plaintextBody" in value:
                shown.add(value["id"])
            for one in value.values():
                walk(one)
        elif isinstance(value, list):
            for one in value:
                walk(one)

    for c in calls:
        if c.ok and c.name in ("get_thread", "get_message"):
            walk(c.result)
    return shown

def check(world, calls):
    proofs = []
    for c in calls:
        if not c.ok:
            continue
        if c.name == "verify_order_owner" and c.arguments.get("order_id") and (c.arguments.get("email") or c.arguments.get("postal_code") or c.arguments.get("customer_id")):
            proofs.append((calls.index(c), (c.result or {}).get("customer_id")))
        elif c.name == "search_orders" and c.arguments.get("postal_code"):
            proofs.append((calls.index(c), (c.result or {}).get("customer_id")))
        elif c.name in ("get_customer_profile", "get_store_credit_balance") and (c.arguments.get("email") or c.arguments.get("postal_code")):
            proofs.append((calls.index(c), (c.result or {}).get("customer_id")))
    if not proofs:
        return "not done: the customer was never verified (verify_order_owner, or search_orders with the postal code)"
    verified = {who for _, who in proofs if who}
    first = min(at for at, _ in proofs)
    for c in calls:
        if c.ok and c.name in ("create_return", "create_exchange", "cancel_order", "update_shipping_address", "cancel_return", "get_shipment_tracking", "get_order_invoice", "get_return_status", "create_support_case"):
            if calls.index(c) < first:
                return f"not done: {c.name} ran before the customer was verified"
            who = c.arguments.get("customer_id")
            if who and verified and who not in verified:
                return f"done wrong: {c.name} acted for {who}, who was not the customer verified in this conversation"
    return None

